//! What a custom stack may be (packages/stacks/src/spec.ts): a small subset
//! of Docker Compose, checked against an allowlist. A key we don't know is an
//! error, never ignored, so a new Compose feature can't slip through.
//!
//! `check` takes the parsed document, a JSON value, and decides exactly as
//! checkStack does, problem for problem; tests/stacks.rs holds it to cases
//! generated by the TypeScript.

use serde::Serialize;
use serde_json::{Map, Value};

use super::image;
use super::js;

pub const SOURCE_BYTES: usize = 64 * 1024;
const SERVICES: usize = 8;
const VOLUMES: usize = 8;
const ENV_VARS: usize = 100;
const ENV_VALUE_BYTES: usize = 4096;
const ARG_BYTES: usize = 4096;
const ARGS: usize = 64;
const EGRESS_HOSTS: usize = 20;
const TMPFS: usize = 4;
const MEMORY_MB: (f64, f64) = (64.0, 16384.0);
const CPUS: (f64, f64) = (0.05, 8.0);
const STORAGE_GB: (f64, f64) = (0.0, 2000.0);

const RESERVED_SERVICE_NAMES: [&str; 2] = ["castor-egress", "castor"];
const RESERVED_SERVICE_PREFIXES: [&str; 2] = ["pc-", "castor-"];
/// Set by the renderer; a stack can't point them elsewhere.
pub const RESERVED_ENV: [&str; 8] = [
    "HTTP_PROXY",
    "HTTPS_PROXY",
    "NO_PROXY",
    "http_proxy",
    "https_proxy",
    "no_proxy",
    "ALL_PROXY",
    "all_proxy",
];
/// Container paths a volume may not cover.
const FORBIDDEN_TARGETS: [&str; 10] = [
    "/", "/proc", "/sys", "/dev", "/etc", "/bin", "/sbin", "/usr", "/lib", "/lib64",
];

const SERVICE_KEYS: [&str; 15] = [
    "image",
    "command",
    "entrypoint",
    "environment",
    "working_dir",
    "user",
    "read_only",
    "tmpfs",
    "volumes",
    "mem_limit",
    "cpus",
    "deploy",
    "healthcheck",
    "depends_on",
    "restart",
];
const SERVICE_HINTS: [(&str, &str); 16] = [
    (
        "ports",
        "ports are not published; set x-castor.web to the service and port to serve",
    ),
    ("networks", "networks are managed by Castor Cloud"),
    ("network_mode", "networks are managed by Castor Cloud"),
    ("privileged", "privileged containers are not allowed"),
    ("cap_add", "extra capabilities are not allowed"),
    ("devices", "devices are not allowed"),
    ("labels", "labels are set by Castor Cloud"),
    ("build", "builds are not supported; use a published image"),
    ("container_name", "container names are set by Castor Cloud"),
    ("volumes_from", "use named volumes"),
    ("pid", "not allowed"),
    ("ipc", "not allowed"),
    ("security_opt", "security options are set by Castor Cloud"),
    ("sysctls", "not allowed"),
    ("extra_hosts", "not allowed"),
    ("dns", "not allowed"),
];
const STACK_HINTS: [(&str, &str); 3] = [
    ("networks", "networks are managed by Castor Cloud"),
    ("secrets", "use environment variables (${secret:name} generates one)"),
    ("configs", "configs are not supported"),
];

#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(untagged)]
pub enum Args {
    One(String),
    Many(Vec<String>),
}

#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Health {
    pub test: Vec<String>,
    #[serde(serialize_with = "number")]
    pub interval_s: f64,
    #[serde(serialize_with = "number")]
    pub timeout_s: f64,
    #[serde(serialize_with = "number")]
    pub retries: f64,
    #[serde(serialize_with = "number")]
    pub start_period_s: f64,
}

#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Mount {
    pub volume: String,
    pub target: String,
    pub read_only: bool,
}

#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Service {
    /// As written, canonical; pinned to a digest at deploy.
    pub image: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub command: Option<Args>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub entrypoint: Option<Args>,
    /// In the order written.
    #[serde(serialize_with = "pairs")]
    pub environment: Vec<(String, String)>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub working_dir: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub user: Option<String>,
    pub tmpfs: Vec<String>,
    pub volumes: Vec<Mount>,
    #[serde(serialize_with = "number")]
    pub memory_mb: f64,
    #[serde(serialize_with = "number")]
    pub cpus: f64,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub healthcheck: Option<Health>,
    pub depends_on: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct Web {
    pub service: String,
    #[serde(serialize_with = "number")]
    pub port: f64,
}

#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Spec {
    /// In the order written.
    #[serde(serialize_with = "pairs")]
    pub services: Vec<(String, Service)>,
    pub volumes: Vec<String>,
    pub web: Web,
    pub egress: Vec<String>,
    #[serde(serialize_with = "number")]
    pub storage_gb: f64,
}

fn pairs<S: serde::Serializer, T: Serialize>(v: &[(String, T)], s: S) -> Result<S::Ok, S::Error> {
    use serde::ser::SerializeMap;
    let mut m = s.serialize_map(Some(v.len()))?;
    for (k, x) in v {
        m.serialize_entry(k, x)?;
    }
    m.end()
}

fn number<S: serde::Serializer>(x: &f64, s: S) -> Result<S::Ok, S::Error> {
    js::num(*x).serialize(s)
}

/// Every problem found (at most 50), joined by "; " as SpecError's message.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SpecError(pub Vec<String>);

impl std::fmt::Display for SpecError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0.join("; "))
    }
}

struct Problems(Vec<String>);

impl Problems {
    fn add(&mut self, at: &str, what: impl std::fmt::Display) {
        if self.0.len() < 50 {
            self.0.push(format!("{at}: {what}"));
        }
    }
}

// ------------------------------------------------------------------ names

fn lower_digit(b: u8) -> bool {
    b.is_ascii_lowercase() || b.is_ascii_digit()
}

/// [a-z][a-z0-9-]{0,29}
fn name(s: &str) -> bool {
    let b = s.as_bytes();
    (1..=30).contains(&b.len()) && b[0].is_ascii_lowercase() && b.iter().all(|c| lower_digit(*c) || *c == b'-')
}

/// [A-Za-z_][A-Za-z0-9_]{0,127}
fn env_key(s: &str) -> bool {
    let b = s.as_bytes();
    (1..=128).contains(&b.len())
        && (b[0].is_ascii_alphabetic() || b[0] == b'_')
        && b.iter().all(|c| c.is_ascii_alphanumeric() || *c == b'_')
}

/// An absolute container path: /seg/seg/ of [A-Za-z0-9._@+-], no empty segment.
pub fn path(s: &str) -> bool {
    s.starts_with('/') && !s.contains("//") && s.bytes().all(|c| c.is_ascii_alphanumeric() || b"._@+-/".contains(&c))
}

fn user_part(s: &str) -> bool {
    let b = s.as_bytes();
    if !b.is_empty() && b.len() <= 10 && b.iter().all(u8::is_ascii_digit) {
        return true;
    }
    (1..=32).contains(&b.len())
        && (b[0].is_ascii_lowercase() || b[0] == b'_')
        && b.iter().all(|c| lower_digit(*c) || *c == b'_' || *c == b'-')
}

fn user(s: &str) -> bool {
    match s.split_once(':') {
        Some((u, g)) => user_part(u) && user_part(g),
        None => user_part(s),
    }
}

/// (*.)?(label.)+[a-z]{2,63}
fn host(s: &str) -> bool {
    let s = s.strip_prefix("*.").unwrap_or(s);
    let parts: Vec<&str> = s.split('.').collect();
    let Some((tld, labels)) = parts.split_last() else {
        return false;
    };
    let label = |l: &str| {
        let b = l.as_bytes();
        (1..=63).contains(&b.len())
            && lower_digit(b[0])
            && lower_digit(b[b.len() - 1])
            && b.iter().all(|c| lower_digit(*c) || *c == b'-')
    };
    !labels.is_empty()
        && (2..=63).contains(&tld.len())
        && tld.bytes().all(|c| c.is_ascii_lowercase())
        && labels.iter().all(|l| label(l))
}

fn ascii_digits(s: &str, max: usize) -> bool {
    (1..=max).contains(&s.len()) && s.bytes().all(|c| c.is_ascii_digit())
}

/// ${secret:name} placeholders in a value, in order: (start, end, name).
pub fn secret_placeholders(v: &str) -> Vec<(usize, usize, &str)> {
    let mut out = Vec::new();
    let mut from = 0;
    while let Some(i) = v[from..].find("${secret:") {
        let start = from + i;
        let body = start + "${secret:".len();
        let n = v[body..]
            .bytes()
            .take_while(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || *c == b'_')
            .count();
        if (1..=32).contains(&n) && v[body + n..].starts_with('}') {
            out.push((start, body + n + 1, &v[body..body + n]));
            from = body + n + 1;
        } else {
            from = start + 1;
        }
    }
    out
}

// ------------------------------------------------------------------ values

fn obj(v: Option<&Value>) -> Option<&Map<String, Value>> {
    v.and_then(Value::as_object)
}

fn only_keys(p: &mut Problems, at: &str, o: &Map<String, Value>, allowed: &[&str], hints: &[(&str, &str)]) {
    for k in js::keys(o) {
        if !allowed.contains(&k) {
            match hints.iter().find(|(h, _)| *h == k) {
                Some((_, hint)) => p.add(at, hint),
                None => p.add(at, format!("\"{k}\" is not supported")),
            }
        }
    }
}

fn no_control(p: &mut Problems, at: &str, s: &str) {
    if s.chars()
        .any(|c| matches!(c, '\u{0}'..='\u{8}' | '\u{b}'..='\u{1f}' | '\u{7f}'))
    {
        p.add(at, "contains control characters");
    }
}

/// "512m", "1g", "1.5GB", 536870912 -> MB (rounded up).
pub fn parse_memory(v: &Value) -> Option<f64> {
    if let Value::Number(n) = v {
        let x = n.as_f64()?;
        return (x.is_finite() && x > 0.0).then(|| (x / (1024.0 * 1024.0)).ceil());
    }
    let s = js::trim(v.as_str()?).to_lowercase();
    let num_end = s.bytes().take_while(u8::is_ascii_digit).count();
    let mut end = num_end;
    if num_end == 0 {
        return None;
    }
    if s[end..].starts_with('.') {
        let frac = s[end + 1..].bytes().take_while(u8::is_ascii_digit).count();
        if frac == 0 {
            return None;
        }
        end += 1 + frac;
    }
    let n: f64 = s[..end].parse().ok()?;
    let unit = s[end..].trim_start_matches(js::is_space);
    let mb = match unit {
        "" | "b" => n / (1024.0 * 1024.0),
        "k" | "kb" => n / 1024.0,
        "m" | "mb" => n,
        "g" | "gb" => n * 1024.0,
        _ => return None,
    };
    (mb > 0.0).then(|| mb.ceil())
}

/// "10s", "1m30s", 5 -> seconds.
fn parse_duration(v: &Value) -> Option<f64> {
    if let Value::Number(n) = v {
        let x = n.as_f64()?;
        return (js::is_integer(x) && x >= 0.0).then_some(x);
    }
    let t = js::trim(v.as_str()?);
    if t.is_empty() {
        return None;
    }
    let mut rest = t;
    let mut total = 0.0;
    for (unit, secs) in [('h', 3600.0), ('m', 60.0), ('s', 1.0)] {
        let d = rest.bytes().take_while(u8::is_ascii_digit).count();
        if d > 0 && rest[d..].starts_with(unit) {
            total += rest[..d].parse::<f64>().ok()? * secs;
            rest = &rest[d + 1..];
        }
    }
    rest.is_empty().then_some(total)
}

fn string_or_args(p: &mut Problems, at: &str, v: Option<&Value>) -> Option<Args> {
    match v {
        None | Some(Value::Null) => None,
        Some(Value::String(s)) => {
            if s.len() > ARG_BYTES {
                p.add(at, "too long");
            }
            Some(Args::One(s.clone()))
        }
        Some(Value::Array(a)) if a.len() <= ARGS && a.iter().all(|x| x.is_string() || x.is_number()) => {
            let args: Vec<String> = a.iter().map(js::string).collect();
            if args.iter().any(|x| x.len() > ARG_BYTES) {
                p.add(at, "argument too long");
            }
            Some(Args::Many(args))
        }
        Some(_) => {
            p.add(at, "must be a string or a list of strings");
            None
        }
    }
}

fn environment(p: &mut Problems, at: &str, v: Option<&Value>) -> Vec<(String, String)> {
    let mut out: Vec<(String, String)> = Vec::new();
    let mut set = |p: &mut Problems, key: &str, value: Option<&Value>| {
        if !env_key(key) {
            return p.add(at, format!("invalid variable name \"{}\"", js::slice(key, 40)));
        }
        if RESERVED_ENV.contains(&key) {
            return p.add(at, format!("{key} is set by Castor Cloud (egress proxy)"));
        }
        let value = match value {
            None | Some(Value::Null) => return p.add(at, format!("{key} needs a value")),
            Some(Value::Array(_) | Value::Object(_)) => return p.add(at, format!("{key} must be a string")),
            Some(v) => js::string(v),
        };
        if value.len() > ENV_VALUE_BYTES {
            return p.add(at, format!("{key} is too long"));
        }
        no_control(p, &format!("{at}.{key}"), &value);
        // A JavaScript object can't hold this key: the TypeScript drops it.
        if key == "__proto__" {
            return;
        }
        match out.iter_mut().find(|(k, _)| k == key) {
            Some(e) => e.1 = value,
            None => out.push((key.to_owned(), value)),
        }
    };
    match v {
        None | Some(Value::Null) => return out,
        Some(Value::Array(items)) => {
            for item in items {
                match item.as_str().and_then(|s| s.split_once('=')) {
                    Some((k, val)) => set(p, k, Some(&Value::String(val.to_owned()))),
                    None => p.add(at, "list entries must be KEY=value"),
                }
            }
        }
        Some(Value::Object(o)) => {
            for k in js::keys(o) {
                set(p, k, o.get(k));
            }
        }
        Some(_) => p.add(at, "must be a map or a list"),
    }
    if out.len() > ENV_VARS {
        p.add(at, format!("at most {ENV_VARS} variables"));
    }
    out
}

fn trim_slashes(s: &str) -> &str {
    s.trim_end_matches('/')
}

fn check_target(p: &mut Problems, at: &str, target: &str) {
    if !path(target) || target.split('/').any(|s| s == "." || s == "..") {
        p.add(at, format!("invalid container path \"{}\"", js::slice(target, 80)));
        return;
    }
    let t = match trim_slashes(target) {
        "" => "/",
        t => t,
    };
    if FORBIDDEN_TARGETS.contains(&t) {
        p.add(at, format!("can't mount over {t}"));
    }
}

fn mounts(p: &mut Problems, at: &str, v: Option<&Value>) -> Vec<Mount> {
    let items = match v {
        None | Some(Value::Null) => return Vec::new(),
        Some(Value::Array(a)) => a,
        Some(_) => {
            p.add(at, "must be a list");
            return Vec::new();
        }
    };
    let mut out = Vec::new();
    for item in items {
        let (volume, target, read_only) = match item {
            Value::String(s) => {
                let parts: Vec<&str> = s.split(':').collect();
                if parts.len() < 2 || parts.len() > 3 || parts.get(2).is_some_and(|m| *m != "ro" && *m != "rw") {
                    p.add(at, format!("\"{}\": use volume-name:/path[:ro]", js::slice(s, 80)));
                    continue;
                }
                (
                    Some(parts[0].to_owned()),
                    Some(parts[1].to_owned()),
                    parts.get(2) == Some(&"ro"),
                )
            }
            Value::Object(o) => {
                only_keys(p, at, o, &["type", "source", "target", "read_only"], &[]);
                if let Some(t) = o.get("type").filter(|t| t.as_str() != Some("volume")) {
                    p.add(
                        at,
                        format!("type \"{}\" is not supported (only named volumes)", js::string(t)),
                    );
                    continue;
                }
                (
                    o.get("source").and_then(Value::as_str).map(str::to_owned),
                    o.get("target").and_then(Value::as_str).map(str::to_owned),
                    o.get("read_only") == Some(&Value::Bool(true)),
                )
            }
            _ => (None, None, false),
        };
        let (Some(volume), Some(target)) = (volume.filter(|v| !v.is_empty()), target.filter(|t| !t.is_empty())) else {
            p.add(at, "each entry needs a volume name and a container path");
            continue;
        };
        if volume.starts_with(['/', '.', '~']) {
            p.add(
                at,
                format!(
                    "\"{}\": host paths are not allowed, use a named volume",
                    js::slice(&volume, 80)
                ),
            );
            continue;
        }
        if !name(&volume) {
            p.add(at, format!("invalid volume name \"{}\"", js::slice(&volume, 40)));
            continue;
        }
        check_target(p, at, &target);
        out.push(Mount {
            volume,
            target,
            read_only,
        });
    }
    out
}

fn health(p: &mut Problems, at: &str, v: Option<&Value>) -> Option<Health> {
    let o = match v {
        None | Some(Value::Null) => return None,
        Some(Value::Object(o)) => o,
        Some(_) => {
            p.add(at, "must be a map");
            return None;
        }
    };
    only_keys(
        p,
        at,
        o,
        &["test", "interval", "timeout", "retries", "start_period"],
        &[],
    );
    let test: Vec<String> = match o.get("test") {
        Some(Value::String(s)) => vec!["CMD-SHELL".into(), s.clone()],
        Some(Value::Array(a))
            if a.iter().all(Value::is_string)
                && matches!(a.first().and_then(Value::as_str), Some("CMD" | "CMD-SHELL")) =>
        {
            a.iter().map(js::string).collect()
        }
        _ => {
            p.add(at, "test must be a string or [CMD|CMD-SHELL, ...]");
            Vec::new()
        }
    };
    if test.iter().any(|a| a.len() > ARG_BYTES) || test.len() > ARGS {
        p.add(at, "test too long");
    }
    let retries = o.get("retries").map_or(3.0, js::number);
    if !js::is_integer(retries) || !(1.0..=20.0).contains(&retries) {
        p.add(at, "retries must be 1-20");
    }
    let mut dur = |key: &str, def: f64, min: f64, max: f64| match o.get(key) {
        None => def,
        Some(v) => match parse_duration(v).filter(|s| (min..=max).contains(s)) {
            Some(s) => s,
            None => {
                p.add(
                    at,
                    format!(
                        "{key} must be between {}s and {}s",
                        js::number_string(min),
                        js::number_string(max)
                    ),
                );
                def
            }
        },
    };
    Some(Health {
        test,
        interval_s: dur("interval", 30.0, 5.0, 3600.0),
        timeout_s: dur("timeout", 10.0, 1.0, 300.0),
        retries: if js::is_integer(retries) { retries } else { 3.0 },
        start_period_s: dur("start_period", 0.0, 0.0, 3600.0),
    })
}

fn resources(p: &mut Problems, at: &str, svc: &Map<String, Value>) -> (f64, f64) {
    let mut mem = svc.get("mem_limit");
    let mut cpus = svc.get("cpus");
    if let Some(deploy) = svc.get("deploy") {
        let at = format!("{at}.deploy");
        match deploy {
            Value::Object(d) => {
                only_keys(p, &at, d, &["resources"], &[]);
                if let Some(res) = d.get("resources") {
                    let at = format!("{at}.resources");
                    match res {
                        Value::Object(r) => {
                            only_keys(p, &at, r, &["limits"], &[]);
                            if let Some(limits) = obj(r.get("limits")) {
                                only_keys(p, &format!("{at}.limits"), limits, &["memory", "cpus"], &[]);
                                // `??=`: a null mem_limit or cpus also takes the deploy limit.
                                if mem.is_none_or(Value::is_null) {
                                    mem = limits.get("memory");
                                }
                                if cpus.is_none_or(Value::is_null) {
                                    cpus = limits.get("cpus");
                                }
                            }
                        }
                        _ => p.add(&at, "must be a map"),
                    }
                }
            }
            _ => p.add(&at, "must be a map"),
        }
    }
    let memory_mb = mem.and_then(parse_memory);
    match memory_mb {
        None => p.add(at, "needs a memory limit (mem_limit: 512m)"),
        Some(m) if m < MEMORY_MB.0 || m > MEMORY_MB.1 => p.add(
            at,
            format!(
                "memory must be between {} MB and {} GB",
                js::number_string(MEMORY_MB.0),
                js::number_string(MEMORY_MB.1 / 1024.0)
            ),
        ),
        Some(_) => {}
    }
    let n = cpus.map_or(f64::NAN, js::number);
    if !n.is_finite() {
        p.add(at, "needs a CPU limit (cpus: 0.5)");
    } else if n < CPUS.0 || n > CPUS.1 {
        p.add(
            at,
            format!(
                "cpus must be between {} and {}",
                js::number_string(CPUS.0),
                js::number_string(CPUS.1)
            ),
        );
    }
    (
        memory_mb.unwrap_or(0.0),
        if n.is_finite() {
            js::round(n * 100.0) / 100.0
        } else {
            0.0
        },
    )
}

fn service(p: &mut Problems, svc_name: &str, v: &Value) -> Option<Service> {
    let at = format!("services.{svc_name}");
    let Some(o) = v.as_object() else {
        p.add(&at, "must be a map");
        return None;
    };
    only_keys(p, &at, o, &SERVICE_KEYS, &SERVICE_HINTS);

    let mut img = String::new();
    match o.get("image") {
        Some(Value::String(s)) => match image::parse(s) {
            Ok(r) => img = r.canonical,
            Err(e) => p.add(&format!("{at}.image"), e),
        },
        _ => p.add(&at, "needs an image"),
    }

    let mut working_dir = None;
    if let Some(w) = o.get("working_dir") {
        match w.as_str().filter(|w| path(w)) {
            Some(w) => working_dir = Some(w.to_owned()),
            None => p.add(&format!("{at}.working_dir"), "must be an absolute path"),
        }
    }

    let mut usr = None;
    if let Some(u) = o.get("user") {
        let u = js::string(u);
        if user(&u) {
            usr = Some(u);
        } else {
            p.add(&format!("{at}.user"), "must be uid[:gid] or name[:group]");
        }
    }

    if o.get("read_only").is_some_and(|r| *r != Value::Bool(true)) {
        p.add(
            &format!("{at}.read_only"),
            "the root filesystem is always read-only; put writable paths on a volume or under tmpfs:",
        );
    }
    let mut tmpfs = Vec::new();
    if let Some(t) = o.get("tmpfs") {
        let one = [t.clone()];
        let list: Option<&[Value]> = match t {
            Value::String(_) => Some(&one),
            Value::Array(a) => Some(a),
            _ => None,
        };
        match list.filter(|l| l.iter().all(Value::is_string) && l.len() <= TMPFS) {
            Some(l) => {
                for x in l.iter().filter_map(Value::as_str) {
                    check_target(p, &format!("{at}.tmpfs"), x);
                    tmpfs.push(trim_slashes(x).to_owned());
                }
            }
            None => p.add(
                &format!("{at}.tmpfs"),
                format!("must be a list of up to {TMPFS} container paths"),
            ),
        }
    }
    if o.get("restart").is_some_and(|r| !r.is_string()) {
        p.add(&format!("{at}.restart"), "must be a string");
    }

    let mut depends_on = Vec::new();
    match o.get("depends_on") {
        None => {}
        Some(Value::Array(a)) if a.iter().all(Value::is_string) => {
            depends_on = a.iter().filter_map(Value::as_str).map(str::to_owned).collect();
        }
        // Conditions are dropped: healthchecks and restarts instead.
        Some(Value::Object(d)) => depends_on = js::keys(d).into_iter().map(str::to_owned).collect(),
        Some(_) => p.add(&format!("{at}.depends_on"), "must be a list of service names"),
    }

    let command = string_or_args(p, &format!("{at}.command"), o.get("command"));
    let entrypoint = string_or_args(p, &format!("{at}.entrypoint"), o.get("entrypoint"));
    for a in [&command, &entrypoint].into_iter().flatten() {
        match a {
            Args::One(s) => no_control(p, &at, s),
            Args::Many(v) => v.iter().for_each(|s| no_control(p, &at, s)),
        }
    }

    let environment = environment(p, &format!("{at}.environment"), o.get("environment"));
    let volumes = mounts(p, &format!("{at}.volumes"), o.get("volumes"));
    let (memory_mb, cpus) = resources(p, &at, o);
    let healthcheck = health(p, &format!("{at}.healthcheck"), o.get("healthcheck"));
    Some(Service {
        image: img,
        command,
        entrypoint,
        environment,
        working_dir,
        user: usr,
        tmpfs,
        volumes,
        memory_mb,
        cpus,
        healthcheck,
        depends_on,
    })
}

fn web_service(s: &str) -> Option<(&str, &str)> {
    let (svc, port) = s.split_once(':')?;
    let b = svc.as_bytes();
    let svc_ok =
        (1..=30).contains(&b.len()) && b[0].is_ascii_lowercase() && b.iter().all(|c| lower_digit(*c) || *c == b'-');
    (svc_ok && ascii_digits(port, 5)).then_some((svc, port))
}

fn castor(p: &mut Problems, v: Option<&Value>, services: &[&str]) -> (Web, Vec<String>, f64) {
    let at = "x-castor";
    let mut web = Web {
        service: if services.len() == 1 {
            services[0].to_owned()
        } else {
            String::new()
        },
        port: 0.0,
    };
    let mut egress = Vec::new();
    let mut storage_gb = 0.0;
    let Some(o) = obj(v) else {
        p.add(at, "missing: set at least x-castor.web (service:port)");
        return (web, egress, storage_gb);
    };
    only_keys(
        p,
        at,
        o,
        &["web", "egress", "storage_gb", "label", "description", "homepage"],
        &[],
    );

    let w = o.get("web");
    if let Some((s, port)) = w.and_then(Value::as_str).and_then(web_service) {
        web = Web {
            service: s.to_owned(),
            port: js::string_to_number(port),
        };
    } else if let Some(port) = w.filter(|w| w.is_number() || w.as_str().is_some_and(|s| ascii_digits(s, 5))) {
        web.port = js::number(port);
    } else {
        p.add(&format!("{at}.web"), "must be service:port, e.g. app:8080");
    }
    if !services.contains(&web.service.as_str()) {
        p.add(&format!("{at}.web"), format!("unknown service \"{}\"", web.service));
    }
    if !(web.port >= 1.0 && web.port <= 65535.0) {
        p.add(&format!("{at}.web"), "invalid port");
    }

    if let Some(e) = o.get("egress") {
        match e.as_array().filter(|a| a.iter().all(Value::is_string)) {
            None => p.add(&format!("{at}.egress"), "must be a list of host names"),
            Some(a) => {
                for h in a.iter().filter_map(Value::as_str) {
                    let h = js::trim(h).to_lowercase();
                    if !egress.contains(&h) {
                        egress.push(h);
                    }
                }
                for h in &egress {
                    if !host(h) {
                        p.add(
                            &format!("{at}.egress"),
                            format!(
                                "invalid host \"{}\" (no IPs, no ports; *.example.com allowed)",
                                js::slice(h, 80)
                            ),
                        );
                    }
                }
                if egress.len() > EGRESS_HOSTS {
                    p.add(&format!("{at}.egress"), format!("at most {EGRESS_HOSTS} hosts"));
                }
            }
        }
    }

    if let Some(s) = o.get("storage_gb") {
        let n = js::number(s);
        if !js::is_integer(n) || n < STORAGE_GB.0 || n > STORAGE_GB.1 {
            p.add(
                &format!("{at}.storage_gb"),
                format!("must be a whole number of GB up to {}", js::number_string(STORAGE_GB.1)),
            );
        } else {
            storage_gb = n;
        }
    }
    (web, egress, storage_gb)
}

fn service_name(n: &str) -> bool {
    name(n)
        && !n.ends_with('-')
        && !RESERVED_SERVICE_NAMES.contains(&n)
        && !RESERVED_SERVICE_PREFIXES.iter().any(|p| n.starts_with(p))
}

/// A stored definition: the customer's document as the portal parsed it,
/// sealed as JSON (storedDefinition in spec.ts). No YAML parser here, so
/// what the portal checked is exactly what is checked and run.
pub fn parse_stored(text: &str) -> Result<Spec, SpecError> {
    if text.len() > SOURCE_BYTES {
        return Err(SpecError(vec![format!(
            "stack definition is larger than {} KB",
            SOURCE_BYTES / 1024
        )]));
    }
    let doc: Value = serde_json::from_str(text).map_err(|_| {
        SpecError(vec![
            "the stored definition is not JSON yet (the TypeScript worker converts it when it starts)".into(),
        ])
    })?;
    check(&doc)
}

/// checkStack: validates a parsed stack document.
pub fn check(doc: &Value) -> Result<Spec, SpecError> {
    let mut p = Problems(Vec::new());
    let Some(d) = doc.as_object() else {
        return Err(SpecError(vec!["the stack must be a map with services:".into()]));
    };
    only_keys(
        &mut p,
        "stack",
        d,
        &["services", "volumes", "x-castor", "version", "name"],
        &STACK_HINTS,
    );

    let mut services: Vec<(String, Service)> = Vec::new();
    let raw = obj(d.get("services"));
    match raw.filter(|s| !s.is_empty()) {
        None => p.add("services", "at least one service is needed"),
        Some(s) => {
            let names = js::keys(s);
            if names.len() > SERVICES {
                p.add("services", format!("at most {SERVICES} services"));
            }
            for n in names {
                if !service_name(n) {
                    p.add("services", format!("invalid service name \"{}\"", js::slice(n, 40)));
                    continue;
                }
                if let Some(svc) = s.get(n).and_then(|v| service(&mut p, n, v)) {
                    services.push((n.to_owned(), svc));
                }
            }
        }
    }

    let mut declared: Vec<String> = Vec::new();
    match d.get("volumes") {
        None | Some(Value::Null) => {}
        Some(Value::Object(v)) => {
            for n in js::keys(v) {
                if !name(n) {
                    p.add("volumes", format!("invalid volume name \"{}\"", js::slice(n, 40)));
                    continue;
                }
                let def = v.get(n);
                if !def.is_some_and(|x| x.is_null() || x.as_object().is_some_and(Map::is_empty)) {
                    p.add(&format!("volumes.{n}"), "driver options are not supported");
                }
                declared.push(n.to_owned());
            }
        }
        Some(_) => p.add("volumes", "must be a map of volume names"),
    }
    if declared.len() > VOLUMES {
        p.add("volumes", format!("at most {VOLUMES} volumes"));
    }

    // Every mount names a declared volume, and each volume belongs to one
    // service: its directory is owned by that service's user.
    let mut owner: Vec<(&str, &str)> = Vec::new();
    for (n, svc) in &services {
        for m in &svc.volumes {
            let at = format!("services.{n}.volumes");
            if !declared.contains(&m.volume) {
                p.add(&at, format!("volume \"{}\" is not declared under volumes:", m.volume));
            }
            match owner.iter_mut().find(|(v, _)| *v == m.volume) {
                Some(o) => {
                    if o.1 != n {
                        p.add(&at, format!("volume \"{}\" is already used by {}", m.volume, o.1));
                    }
                    o.1 = n;
                }
                None => owner.push((&m.volume, n)),
            }
        }
        for dep in &svc.depends_on {
            // Stricter than `d in doc.services`, which also finds "toString".
            if !services.iter().any(|(s, _)| s == dep) && !raw.is_some_and(|r| r.contains_key(dep)) {
                p.add(
                    &format!("services.{n}.depends_on"),
                    format!("unknown service \"{dep}\""),
                );
            }
        }
        if svc.depends_on.contains(n) {
            p.add(&format!("services.{n}.depends_on"), "can't depend on itself");
        }
    }

    let names: Vec<&str> = services.iter().map(|(n, _)| n.as_str()).collect();
    let (web, egress, storage_gb) = castor(&mut p, d.get("x-castor"), &names);
    if !declared.is_empty() && storage_gb == 0.0 {
        p.add("x-castor.storage_gb", "volumes need storage: set storage_gb (e.g. 10)");
    }
    if !p.0.is_empty() {
        return Err(SpecError(p.0));
    }
    Ok(Spec {
        services,
        volumes: declared,
        web,
        egress,
        storage_gb,
    })
}

// ------------------------------------------------------------------ units

pub const MEMORY_UNIT_MB: f64 = 256.0;
pub const CPU_UNIT: f64 = 0.25;
pub const STORAGE_UNIT_GB: f64 = 10.0;

/// What a stack books (@pc/pricing stacks.ts), rounded up.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Units {
    pub memory_units: i64,
    pub cpu_units: i64,
    pub storage_units: i64,
}

impl std::ops::Add for Units {
    type Output = Units;
    fn add(self, o: Units) -> Units {
        Units {
            memory_units: self.memory_units + o.memory_units,
            cpu_units: self.cpu_units + o.cpu_units,
            storage_units: self.storage_units + o.storage_units,
        }
    }
}

impl Units {
    pub fn fits(self, booked: Units) -> bool {
        self.memory_units <= booked.memory_units
            && self.cpu_units <= booked.cpu_units
            && self.storage_units <= booked.storage_units
    }
}

fn ceil_units(x: f64) -> i64 {
    // Bounded by the spec limits, so the conversion is exact.
    #[allow(clippy::cast_possible_truncation)]
    let n = x.ceil() as i64;
    n
}

impl Spec {
    pub fn units(&self) -> Units {
        let memory: f64 = self.services.iter().map(|(_, s)| s.memory_mb).sum();
        let cpus = js::round(self.services.iter().map(|(_, s)| s.cpus).sum::<f64>() * 100.0) / 100.0;
        Units {
            memory_units: ceil_units(memory / MEMORY_UNIT_MB),
            // Round first so float noise (0.1 + 0.2) never books an extra unit.
            cpu_units: ceil_units(js::round((cpus / CPU_UNIT) * 1000.0) / 1000.0),
            storage_units: ceil_units(self.storage_gb / STORAGE_UNIT_GB),
        }
    }

    /// Names of the generated secrets it refers to, sorted.
    pub fn secret_names(&self) -> Vec<String> {
        let mut names: Vec<String> = Vec::new();
        for (_, s) in &self.services {
            for (_, v) in &s.environment {
                for (_, _, n) in secret_placeholders(v) {
                    if !names.iter().any(|x| x == n) {
                        names.push(n.to_owned());
                    }
                }
            }
        }
        names.sort();
        names
    }

    /// The spec as a compose document again (how a checked spec is stored
    /// and read back through `check`).
    pub fn to_document(&self) -> Value {
        let mut services = Map::new();
        for (n, s) in &self.services {
            let mut o = Map::new();
            o.insert("image".into(), Value::from(s.image.clone()));
            let args = |a: &Args| match a {
                Args::One(x) => Value::from(x.clone()),
                Args::Many(v) => v.iter().cloned().map(Value::from).collect(),
            };
            if let Some(c) = &s.command {
                o.insert("command".into(), args(c));
            }
            if let Some(e) = &s.entrypoint {
                o.insert("entrypoint".into(), args(e));
            }
            o.insert(
                "environment".into(),
                Value::Object(
                    s.environment
                        .iter()
                        .map(|(k, v)| (k.clone(), Value::from(v.clone())))
                        .collect(),
                ),
            );
            if let Some(w) = &s.working_dir {
                o.insert("working_dir".into(), Value::from(w.clone()));
            }
            if let Some(u) = &s.user {
                o.insert("user".into(), Value::from(u.clone()));
            }
            o.insert("tmpfs".into(), s.tmpfs.iter().cloned().map(Value::from).collect());
            o.insert(
                "volumes".into(),
                s.volumes
                    .iter()
                    .map(|m| {
                        serde_json::json!({ "type": "volume", "source": m.volume, "target": m.target, "read_only": m.read_only })
                    })
                    .collect(),
            );
            o.insert(
                "mem_limit".into(),
                Value::from(format!("{}m", js::number_string(s.memory_mb))),
            );
            o.insert("cpus".into(), js::num(s.cpus));
            if let Some(h) = &s.healthcheck {
                o.insert(
                    "healthcheck".into(),
                    serde_json::json!({
                        "test": h.test,
                        "interval": js::num(h.interval_s),
                        "timeout": js::num(h.timeout_s),
                        "retries": js::num(h.retries),
                        "start_period": js::num(h.start_period_s),
                    }),
                );
            }
            o.insert(
                "depends_on".into(),
                s.depends_on.iter().cloned().map(Value::from).collect(),
            );
            services.insert(n.clone(), Value::Object(o));
        }
        let mut castor = Map::new();
        castor.insert(
            "web".into(),
            Value::from(format!("{}:{}", self.web.service, js::number_string(self.web.port))),
        );
        castor.insert("egress".into(), self.egress.iter().cloned().map(Value::from).collect());
        castor.insert("storage_gb".into(), js::num(self.storage_gb));
        serde_json::json!({
            "services": services,
            "volumes": self.volumes.iter().map(|v| (v.clone(), Value::Null)).collect::<Map<String, Value>>(),
            "x-castor": castor,
        })
    }

    pub fn service(&self, name: &str) -> Option<&Service> {
        self.services.iter().find(|(n, _)| n == name).map(|(_, s)| s)
    }
}

pub fn stack_storage_mb(units: i64) -> i64 {
    units * 10 * 1024
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matchers() {
        assert!(path("/") && path("/a/b/") && path("/a@b+c"));
        assert!(!path("a") && !path("//a") && !path("/a//b") && !path("/a b"));
        assert!(host("a.example.com") && host("*.example.org") && host("x-1.io"));
        assert!(!host("*") && !host("com") && !host("10.0.0.1") && !host("-a.com") && !host("a-.com") && !host("a.c"));
        assert!(user("1000:1000") && user("node") && user("_x:www-data"));
        assert!(!user("root;id") && !user("12345678901") && !user("A") && !user("a:") && !user(""));
        assert_eq!(
            secret_placeholders("x${secret:db}${secret:}${secret:A}${secret:b_2}"),
            [(1, 13, "db"), (34, 47, "b_2")]
        );
        assert_eq!(parse_duration(&Value::from("1m30s")), Some(90.0));
        assert_eq!(parse_duration(&Value::from("30s1m")), None);
        assert_eq!(parse_duration(&Value::from("1h")), Some(3600.0));
        assert_eq!(parse_duration(&Value::from("m")), None);
    }
}
